float player_win_rate(int side)
{
  card_image_rec *cards [2];
  card_image_rec *card;
  uint wins;
  int games;
  float rate;
  char self = side;
  
  cards[self] = card = card_image_get(self);
  wins = card->header.all_win;
  games = wins + card->header.all_lose;
  if (games != 0) {
    rate = (float)wins / (float)games;
  }
  else {
    rate = 0.0;
  }
  return rate * 100.0;
}

